import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { JSDOM } from 'jsdom';

import { directDownload, initToolIntent } from './toolIntent.js';

// The markup is the server's: generated by the Go test
// handlers/resource TestToolIntentFixturesAreCurrent from the real
// templates, so a renamed form class fails here instead of on the page.
function page(name) {
    const html = readFileSync(new URL(`./__fixtures__/tool-intent-${name}.html`, import.meta.url), 'utf8');
    const dom = new JSDOM(`<!doctype html><body>${html}</body>`, { url: 'https://webtor.io/08ada5a7a6183aae1e09d831df6748d566095a10?tool=magnet-to-torrent' });
    const doc = dom.window.document;
    // jsdom does not navigate; a submit it cannot perform only logs noise.
    doc.addEventListener('submit', (e) => e.preventDefault());
    const scrolled = [];
    dom.window.Element.prototype.scrollIntoView = function (opts) { scrolled.push([this.id, opts]); };
    return { doc, win: dom.window, scrolled };
}

// Every click that reaches a submit button, in order, by its umami event.
function recordPresses(doc) {
    const pressed = [];
    doc.addEventListener('click', (e) => {
        const b = e.target.closest('button[type=submit]');
        if (b) pressed.push(b.getAttribute('data-umami-event') + (b.dataset.umamiEventFormat ? ':' + b.dataset.umamiEventFormat : ''));
    }, true);
    return pressed;
}

function pressLine(doc, win) {
    const link = doc.querySelector('[data-tool-intent-direct]');
    assert.ok(link, 'the fixture has the line');
    const ev = new win.MouseEvent('click', { bubbles: true, cancelable: true });
    link.dispatchEvent(ev);
    return ev;
}

test('a multi-file torrent: the line presses the TAR archive of the directory', () => {
    const { doc, win, scrolled } = page('multi');
    // The server's markup as the browser parses it: file.html's trailing
    // `<div … />` leaves #file open, so #list sits inside it. The script
    // must not take the archive for the file because of that.
    assert.ok(doc.querySelector('#file #list'), 'fixture reflects the real nesting');
    const pressed = recordPresses(doc);
    initToolIntent(doc.body, doc);
    const ev = pressLine(doc, win);
    assert.equal(ev.defaultPrevented, true, 'the #content jump is replaced by the press');
    assert.deepEqual(pressed, ['download-dir:tar'], 'the directory archive, TAR (the default), and nothing else');
    assert.deepEqual(scrolled, [], 'the archive reports into its modal, the page stays put');
});

test('a single-file torrent: the line presses the file download and brings its card into view', () => {
    const { doc, win, scrolled } = page('single');
    const pressed = recordPresses(doc);
    initToolIntent(doc.body, doc);
    const ev = pressLine(doc, win);
    assert.equal(ev.defaultPrevented, true);
    assert.deepEqual(pressed, ['download'], 'the file card\'s Download, not Watch');
    assert.equal(scrolled.length, 1);
    assert.equal(scrolled[0][0], 'file');
    assert.equal(scrolled[0][1].block, 'nearest', 'no jump when the card is already on screen');
});

test('the button is looked up at click time: a swapped #list is the one pressed', () => {
    const { doc, win } = page('multi');
    initToolIntent(doc.body, doc);
    // Picking a file or a subdirectory re-renders #list; the buttons that
    // were there on load are gone.
    const list = doc.getElementById('list');
    list.innerHTML = list.innerHTML.replaceAll('dir-sintel', 'dir-extras');
    let hit = null;
    doc.addEventListener('click', (e) => {
        const b = e.target.closest('button[type=submit]');
        if (b) hit = b.closest('form').getAttribute('data-async-target');
    }, true);
    pressLine(doc, win);
    assert.equal(hit, '#log-dir-extras');
});

test('nothing to press: the link keeps its #content jump', () => {
    const { doc, win } = page('multi');
    doc.getElementById('list').remove();
    doc.getElementById('file').remove();
    assert.equal(directDownload(doc), null);
    initToolIntent(doc.body, doc);
    const ev = pressLine(doc, win);
    assert.equal(ev.defaultPrevented, false);
});

test('a page without the line: nothing is bound, nothing throws', () => {
    const { doc } = page('multi');
    doc.getElementById('resource-header').remove();
    assert.doesNotThrow(() => initToolIntent(doc.body, doc));
});
